export const source="// Imports — public tools, primitive definitions and reusable orchestration.\n// Examples name imports so you can trace each tool to its module.\n// Alternative: import * as manifold from '@manifold/author';\n// Then use manifold.createGraphWorkspace(), manifold.gain, etc.\nimport {\n  fixedGain as fixedGainDefinition,\n  mixer as mixerDefinition,\n  retrospectiveCapture as retrospectiveCaptureDefinition,\n  svf as svfDefinition,\n} from '@manifold/author/primitives';\nimport {\n  GraphContractError,\n  GraphWorkspace,\n  createGraphWorkspace,\n  createLiveGraphSession,\n} from '@manifold/author';\nimport { chooseMainVoice } from '@manifold/author/examples/main-voice-control';\nimport { oscillatorPreviewCurves } from '@manifold/author/examples/oscillator-preview';\nimport { adsr as adsrDefinition } from '@manifold/author/primitives';\n\n// Reusable graph definition — original voice and routing composition.\nconst MAIN_SYNTH = '/midi/synth';\nconst voiceBase = (index) => `${MAIN_SYNTH}/voice/${index}`;\nconst nodePath = (index, name) => `${voiceBase(index)}/nodes/${name}`;\nconst ranges = {\n  waveform: [0, 7, 1, true],\n  pulseWidth: [0.01, 0.99, 0.5],\n  drive: [0, 20, 0],\n  driveShape: [0, 3, 0, true],\n  driveBias: [-1, 1, 0],\n  driveMix: [0, 1, 1],\n  unison: [1, 8, 1, true],\n  detune: [0, 100, 0],\n  spread: [0, 1, 0],\n  'blend/amount': [0, 1, 0.5],\n};\nconst oscillatorIds = {\n  waveform: 0,\n  pulseWidth: 4,\n  drive: 5,\n  driveShape: 6,\n  driveBias: 7,\n  driveMix: 8,\n  unison: 10,\n  detune: 11,\n  spread: 12,\n};\n/** A real Main voice branch. A missing sample input is silent, as in the old graph. */\nfunction addMainWaveVoice(graph, { index, firstNodeId, sample = null }) {\n  const add = (type, name, offset) => {\n    const node = graph.add(type.startsWith('mixer') ? 'mixer' : type, {\n      id: firstNodeId + offset,\n      config: type.startsWith('mixer') ? { inputs: Number(type.slice(5)) } : {},\n    });\n    graph.registerInstance(nodePath(index, name), node);\n    return node;\n  };\n  const oscillator = add('extended-oscillator', 'oscillator', 0);\n  const mix = add('crossfader', 'mix', 1);\n  const direction = add('crossfader', 'direction', 2);\n  const select = add('crossfader', 'base_select', 3);\n  const branches = add('mixer3', 'branches', 4);\n  const voice = add('mixer4', 'output', 5);\n  for (const node of [mix, direction]) {\n    graph.connect(oscillator.output('out'), node.input('a'));\n    if (sample) graph.connect(sample, node.input('b'));\n  }\n  graph.setParameter(select, 0, -1);\n  graph.connect(mix.output('out'), select.input('a'));\n  graph.connect(direction.output('out'), select.input('b'));\n  graph.setParameter(branches, 2, 0).setParameter(branches, 3, 0);\n  graph.connect(select.output('out'), branches.input('in-1'));\n  for (let input = 1; input <= 3; input++) graph.setParameter(voice, input, 0);\n  graph.connect(branches.output('out'), voice.input('in-4'));\n  graph.registerParameter(`${voiceBase(index)}/freq`, oscillator, 1, {\n    min: 20,\n    max: 8000,\n    default: 220,\n  });\n  graph.registerParameter(`${voiceBase(index)}/amp`, oscillator, 2, {\n    min: 0,\n    max: 0.5,\n    default: 0,\n  });\n  graph.registerControl(`${voiceBase(index)}/gate`, {\n    min: 0,\n    max: 1,\n    default: 0,\n  });\n  return { oscillator, mix, direction, select, branches, output: voice };\n}\n/** Eight independent authored voices; scripts may inspect and replace every node. */\nfunction addMainWaveVoices(graph, { firstNodeId = 10, mixerId = 60 } = {}) {\n  const mixer = graph.add(mixerDefinition.type, {\n    id: mixerId,\n    config: { inputs: 8 },\n  });\n  graph.registerInstance(`${MAIN_SYNTH}/nodes/voice_mixer`, mixer);\n  const voices = Array.from({ length: 8 }, (_, index) => {\n    const voice = addMainWaveVoice(graph, {\n      index: index + 1,\n      firstNodeId: firstNodeId + index * 6,\n    });\n    graph.connect(voice.output.output('out'), mixer.input(`in-${index + 1}`));\n    return voice;\n  });\n  for (const [key, [min, max, value, discrete = false]] of Object.entries(ranges)) {\n    graph.registerControl(`${MAIN_SYNTH}/${key}`, {\n      min,\n      max,\n      default: value,\n      discrete,\n    });\n  }\n  return { voices, output: mixer };\n}\n/** Main's shared SVF, from midisynth_integration.applyFilterDefaults.\n * The caller chooses its placement in the authored audio graph.\n */\nfunction addMainSynthFilter(graph, { input, nodeId = 130 } = {}) {\n  const filter = graph.add(svfDefinition.type, { id: nodeId });\n  graph.registerInstance(`${MAIN_SYNTH}/nodes/filter`, filter);\n  graph.connect(input, filter.input('audio'));\n  for (const [id, name, min, max, value] of [\n    [0, 'filterType', 0, 3, 0],\n    [1, 'cutoff', 80, 16000, 3200],\n    [2, 'resonance', 0.1, 2, 0.75],\n  ])\n    graph.registerParameter(`${MAIN_SYNTH}/${name}`, filter, id, {\n      min,\n      max,\n      default: value,\n    });\n  // The public SVF is fully wet with unity drive, matching these old defaults.\n  return filter;\n}\n/** main.lua dry/monitor/master routing, with caller-authored loop and synth buses.\n * The caller supplies real layer inputs/outputs; this function does not substitute\n * an independent LoopCapture for the legacy LoopLayer behavior.\n */\nfunction addMainSignalBranches(\n  graph,\n  { synth, layerInputs = [], layerOutputs = [], firstNodeId = 70, connectOutput = true } = {},\n) {\n  if (!synth || layerInputs.length > 4 || layerOutputs.length > 4) {\n    throw new GraphContractError(\n      'invalid-main-branches',\n      'Provide a synth output and at most four layer buses',\n    );\n  }\n  const add = (name, type, offset) => {\n    const node = graph.add(type.startsWith('mixer') ? 'mixer' : type, {\n      id: firstNodeId + offset,\n      config: type.startsWith('mixer') ? { inputs: Number(type.slice(5)) } : {},\n    });\n    graph.registerInstance(`/main/nodes/${name}`, node);\n    return node;\n  };\n  const trim = add('input_trim', 'gain', 0),\n    monitor = add('input_monitor', 'gain', 1);\n  const synthMonitor = add('synth_monitor', 'gain', 2),\n    send = add('synth_send', 'gain', 3);\n  const layers = add('layer_mixer', 'mixer4', 4),\n    mix = add('main_mixer', 'mixer3', 5);\n  const master = add('master', 'gain', 6);\n  for (const node of [trim, monitor, send, master]) graph.setParameter(node, 0, 1);\n  graph.setParameter(synthMonitor, 0, 0.8);\n  graph.connect(graph.input.output('out'), trim.input('audio'));\n  graph.connect(trim.output('out'), monitor.input('audio'));\n  graph.connect(synth, synthMonitor.input('audio'));\n  graph.connect(synth, send.input('audio'));\n  // The legacy graph permits fan-in to a layer input. Explicit sum nodes retain\n  // the two contributions in the portable contract's single-source input model.\n  layerInputs.forEach((target, index) => {\n    const sum = add(`layer_${index + 1}_input`, 'sum2', 7 + index);\n    graph.connect(trim.output('out'), sum.input('a'));\n    graph.connect(send.output('out'), sum.input('b'));\n    graph.connect(sum.output('out'), target);\n  });\n  layerOutputs.forEach((source, index) => graph.connect(source, layers.input(`in-${index + 1}`)));\n  graph.connect(synthMonitor.output('out'), mix.input('in-1'));\n  graph.connect(layers.output('out'), mix.input('in-2'));\n  graph.connect(monitor.output('out'), mix.input('in-3'));\n  graph.connect(mix.output('out'), master.input('audio'));\n  if (connectOutput) graph.connect(master.output('out'), graph.output.input('in'));\n  for (const [name, node, value] of [\n    ['inputTrim', trim, 1],\n    ['inputMonitor', monitor, 1],\n    ['output', synthMonitor, 0.8],\n    ['captureSend', send, 1],\n    ['master', master, 1],\n  ]) {\n    graph.registerParameter(`${MAIN_SYNTH}/${name}`, node, 0, {\n      min: 0,\n      max: 2,\n      default: value,\n    });\n  }\n  return { trim, monitor, synthMonitor, send, layers, mix, master };\n}\n// Graph definition — construct inspectable primitives with stable identities.\nfunction buildGraph({ captureLayers = false } = {}) {\n  const graph = createGraphWorkspace().setInputSource('external');\n  const { output } = addMainWaveVoices(graph);\n  const captures = captureLayers\n    ? Array.from({ length: 4 }, (_, index) => {\n        const node = graph.add(retrospectiveCaptureDefinition.type, {\n          id: 90 + index,\n        });\n        graph.registerInstance(`/main/layer/${index + 1}/capture`, node);\n        return node.input('audio');\n      })\n    : [];\n  addMainSignalBranches(graph, {\n    synth: output.output('out'),\n    layerInputs: captures,\n  });\n  return graph;\n}\n// Host integration — the session publishes edits only after audio acceptance.\n\nexport default function createProject() {\n  // Audio interface and composition — shared synth/input routing.\n  const graph = buildGraph();\n  // The original shared Filter follows the voice mixer. Dry monitoring stays dry.\n  const sharedFilter = addMainSynthFilter(graph, {\n    input: graph.findInstance(MAIN_SYNTH + '/nodes/voice_mixer').output('out'),\n  });\n  for (const name of ['synth_monitor', 'synth_send']) {\n    const target = graph.findInstance('/main/nodes/' + name).input('audio');\n    graph.disconnect(target);\n    graph.connect(sharedFilter.output('out'), target);\n  }\n  const ADSR_BASE = MAIN_SYNTH + '/adsr';\n  const envelopeId = (index) => 110 + index;\n  for (let index = 0; index < 8; index++) {\n    const envelope = graph.add(adsrDefinition.type, { id: envelopeId(index) });\n    graph.registerInstance(voiceBase(index + 1) + '/nodes/envelope', envelope);\n    const output = graph.findInstance(nodePath(index + 1, 'output'));\n    const mixer = graph.findInstance(MAIN_SYNTH + '/nodes/voice_mixer');\n    graph.disconnect(mixer.input('in-' + (index + 1)));\n    graph.connect(output.output('out'), envelope.input('audio'));\n    graph.connect(envelope.output('out'), mixer.input('in-' + (index + 1)));\n  }\n  for (const [name, min, max, value] of [\n    ['attack', 0.001, 5, 0.05],\n    ['decay', 0.001, 5, 0.2],\n    ['sustain', 0, 1, 0.7],\n    ['release', 0.001, 10, 0.4],\n  ])\n    graph.registerControl(ADSR_BASE + '/' + name, { min, max, default: value });\n  const control = (name, label, group, choices) => ({\n    id: name,\n    type: [\n      'output',\n      'inputTrim',\n      'inputMonitor',\n      'master',\n      'filterType',\n      'cutoff',\n      'resonance',\n    ].includes(name)\n      ? 'parameter'\n      : 'control',\n    path: MAIN_SYNTH + '/' + name,\n    label,\n    group,\n    ...(choices ? { choices } : {}),\n  });\n  // Presentation — one declared UI serves retained and immediate renderers.\n  const view = [\n    {\n      id: 'wave-preview',\n      type: 'curve',\n      points: [],\n      label: 'WAVE MODE',\n      color: '#38bdf8',\n      group: 'Preview',\n    },\n    {\n      id: 'drive-preview',\n      type: 'curve',\n      points: [],\n      label: 'DRIVE',\n      color: '#f97316',\n      group: 'Preview',\n    },\n    control('waveform', 'Waveform', 'Wave', [\n      'Sine',\n      'Saw',\n      'Square',\n      'Triangle',\n      'Blend',\n      'Noise',\n      'Pulse',\n      'SuperSaw',\n    ]),\n    control('pulseWidth', 'Pulse width', 'Wave'),\n    control('drive', 'Drive', 'Wave'),\n    control('driveShape', 'Drive shape', 'Wave', ['Soft', 'Hard', 'Clip', 'Fold']),\n    control('driveBias', 'Bias', 'Wave'),\n    control('driveMix', 'Drive mix', 'Wave'),\n    control('unison', 'Unison', 'Tone'),\n    control('detune', 'Detune (cents)', 'Tone'),\n    control('spread', 'Stereo spread', 'Tone'),\n    control('filterType', 'Filter mode', 'Tone', ['Low pass', 'Band pass', 'High pass', 'Notch']),\n    control('cutoff', 'Filter cutoff (Hz)', 'Tone'),\n    control('resonance', 'Filter resonance', 'Tone'),\n    ...['attack', 'decay', 'sustain', 'release'].map((name) => ({\n      id: name,\n      type: 'control',\n      path: ADSR_BASE + '/' + name,\n      label: name[0].toUpperCase() + name.slice(1),\n      group: 'ADSR',\n    })),\n    control('output', 'Synth monitor', 'Routing'),\n    control('inputTrim', 'Input trim', 'Routing'),\n    control('inputMonitor', 'Input monitor', 'Routing'),\n    control('master', 'Master', 'Routing'),\n    { id: 'keyboard', type: 'keyboard', firstNote: 48, noteCount: 25, group: 'Play' },\n  ];\n  let previewKey = '',\n    previewModel;\n  function paint(ui, snapshot) {\n    const values = Object.fromEntries(\n      snapshot.graph.controls\n        .filter((c) => c.path.startsWith(MAIN_SYNTH + '/'))\n        .map((c) => [c.path.slice(MAIN_SYNTH.length + 1), c.value]),\n    );\n    const key = JSON.stringify(\n      ['waveform', 'pulseWidth', 'drive', 'driveShape', 'driveBias'].map((k) => values[k]),\n    );\n    if (key !== previewKey) {\n      previewKey = key;\n      previewModel = oscillatorPreviewCurves(values);\n    }\n    for (const { path, type, ...options } of view) {\n      if (type === 'curve')\n        ui.curve({\n          ...options,\n          points: options.id === 'drive-preview' ? previewModel.drive : previewModel.wave,\n          color: options.id === 'drive-preview' ? '#f97316' : previewModel.color,\n          label: options.id === 'drive-preview' ? 'DRIVE' : previewModel.label,\n        });\n      else if (type === 'keyboard')\n        ui.keyboard({\n          ...options,\n          activeNotes: (snapshot.eventState?.voices ?? []).filter((v) => v.gate).map((v) => v.note),\n        });\n      else if (type === 'parameter') ui.parameter(path, options);\n      else ui.control(path, options);\n    }\n  }\n  // Live controls — the host invokes this mapper for accepted UI gestures.\n  function onControl(session, path, value) {\n    if (path.startsWith(ADSR_BASE + '/')) {\n      const id = ['attack', 'decay', 'sustain', 'release'].indexOf(path.split('/').at(-1));\n      return session.parametersWithControl(\n        Array.from({ length: 8 }, (_, i) => ({ nodeId: envelopeId(i), id, value })),\n        { path, value },\n      );\n    }\n    const project = session.toProject(),\n      endpoint = project.endpoints.find((e) => e.path === path);\n    if (endpoint) return session.parameterPath(path, value);\n    const name = path.slice((MAIN_SYNTH + '/').length);\n    const instances = new Map(project.instances.map((i) => [i.path, i.nodeId]));\n    if (!path.startsWith(MAIN_SYNTH + '/') || !Object.hasOwn(ranges, name))\n      throw new GraphContractError('unknown-control', 'Unknown Main Wave control ' + path);\n    const edits = [];\n    for (let index = 1; index <= 8; index++) {\n      if (name === 'blend/amount')\n        for (const branch of ['mix', 'direction'])\n          edits.push({\n            nodeId: instances.get(nodePath(index, branch)),\n            id: 0,\n            value: value * 2 - 1,\n          });\n      else\n        edits.push({\n          nodeId: instances.get(nodePath(index, 'oscillator')),\n          id: oscillatorIds[name],\n          value,\n        });\n    }\n    return session.parametersWithControl(edits, { path, value });\n  }\n  // Live events — keyboard/MIDI enter through the returned onEvent hook.\n  const eventStateSchema = 'manifold.main-wave.keyboard.v1';\n  const startVoice = (session, index, note, amplitude) => {\n    const project = session.toProject(),\n      nodeId = project.instances.find((i) => i.path === nodePath(index + 1, 'oscillator')).nodeId;\n    session.parametersWithControl(\n      [\n        { nodeId, id: 1, value: Math.max(20, Math.min(8000, 440 * 2 ** ((note - 69) / 12))) },\n        { nodeId, id: 2, value: amplitude },\n      ],\n      { path: voiceBase(index + 1) + '/gate', value: 1 },\n    );\n  };\n  const releaseVoice = (session, index) =>\n    session.parametersWithControl([{ nodeId: envelopeId(index), id: 4, value: 0 }], {\n      path: voiceBase(index + 1) + '/gate',\n      value: 0,\n    });\n  const silenceVoice = (session, index) => {\n    const nodeId = session\n      .toProject()\n      .instances.find((i) => i.path === nodePath(index + 1, 'oscillator')).nodeId;\n    return session.parametersWithControl([{ nodeId, id: 2, value: 0 }], {\n      path: voiceBase(index + 1) + '/gate',\n      value: 0,\n    });\n  };\n\n  // Allocation is project orchestration; envelopes and oscillator samples run in Rust.\n  const emptyVoice = () => ({\n    active: false,\n    note: null,\n    gate: 0,\n    stamp: 0,\n    owner: '',\n    channel: 0,\n    startedAt: 0,\n    releasedAt: 0,\n    releaseLevel: 0,\n    velocity: 0,\n    keyDown: 0,\n    envelopeStage: 'idle',\n    envelopeLevel: 0,\n  });\n  const eventState = { stamp: 0, sustain: {}, voices: Array.from({ length: 8 }, emptyVoice) };\n  function onEvent(session, event, state) {\n    const project = session.toProject(),\n      controls = new Map(project.controls.map((c) => [c.path, c.value]));\n    const get = (name) => controls.get(ADSR_BASE + '/' + name);\n    const owner = String(event.owner ?? 'user'),\n      channel = event.channel ?? 0;\n    if (!Number.isInteger(channel) || channel < 0 || channel > 15)\n      throw new GraphContractError('invalid-event', 'Invalid MIDI channel');\n    const next = structuredClone(state);\n    for (const voice of next.voices) {\n      const age = Math.max(0, event.at - voice.startedAt);\n      if (voice.gate) {\n        voice.envelopeLevel =\n          age < get('attack')\n            ? age / get('attack')\n            : age < get('attack') + get('decay')\n              ? 1 - ((1 - get('sustain')) * (age - get('attack'))) / get('decay')\n              : get('sustain');\n        voice.envelopeStage = 'sustain';\n      } else if (voice.active) {\n        voice.envelopeLevel =\n          voice.releaseLevel * Math.max(0, 1 - (event.at - voice.releasedAt) / get('release'));\n        voice.envelopeStage = voice.envelopeLevel > 0 ? 'release' : 'idle';\n        if (voice.envelopeStage === 'idle') voice.active = false;\n      }\n    }\n    if (event.type === 'panic') {\n      for (const [index, voice] of next.voices.entries()) {\n        if (\n          (event.owner == null || voice.owner === owner) &&\n          (event.channel == null || voice.channel === channel)\n        ) {\n          silenceVoice(session, index);\n          session.parameters([{ nodeId: envelopeId(index), id: 4, value: 0 }]);\n          next.voices[index] = emptyVoice();\n        }\n      }\n      for (const key of Object.keys(next.sustain)) {\n        const separator = key.lastIndexOf(':');\n        if (\n          (event.owner == null || key.slice(0, separator) === owner) &&\n          (event.channel == null || Number(key.slice(separator + 1)) === channel)\n        )\n          delete next.sustain[key];\n      }\n      return next;\n    }\n    if (event.type === 'all-notes-off') {\n      for (const [index, voice] of next.voices.entries()) {\n        if (voice.gate && voice.owner === owner && voice.channel === channel) {\n          voice.keyDown = 0;\n          if (next.sustain?.[owner + ':' + channel]) continue;\n          releaseVoice(session, index);\n          voice.gate = 0;\n          voice.releasedAt = event.at;\n          voice.releaseLevel = voice.envelopeLevel;\n          voice.envelopeStage = 'release';\n        }\n      }\n      return next;\n    }\n    if (event.type === 'sustain') {\n      if (typeof event.down !== 'boolean')\n        throw new GraphContractError('invalid-event', 'Sustain must be boolean');\n      next.sustain ??= {};\n      next.sustain[owner + ':' + channel] = event.down;\n      if (!event.down)\n        for (const [index, voice] of next.voices.entries()) {\n          if (voice.gate && !voice.keyDown && voice.owner === owner && voice.channel === channel) {\n            releaseVoice(session, index);\n            voice.gate = 0;\n            voice.releasedAt = event.at;\n            voice.releaseLevel = voice.envelopeLevel;\n            voice.envelopeStage = 'release';\n          }\n        }\n      return next;\n    }\n    if (\n      !['note-on', 'note-off'].includes(event.type) ||\n      !Number.isInteger(event.note) ||\n      event.note < 0 ||\n      event.note > 127\n    )\n      throw new GraphContractError('invalid-event', 'Expected a MIDI note-on, note-off or panic');\n    if (event.type === 'note-on') {\n      const velocity = event.velocity ?? 100;\n      if (!Number.isInteger(velocity) || velocity < 1 || velocity > 127)\n        throw new GraphContractError('invalid-event', 'Invalid note velocity');\n      const index = chooseMainVoice(next.voices),\n        stamp = (next.stamp % 1000000) + 1;\n      startVoice(session, index, event.note, Math.min(0.4, 0.03 + (velocity / 127) * 0.37));\n      session.parameters([\n        { nodeId: envelopeId(index), id: 4, value: 1 },\n        { nodeId: envelopeId(index), id: 5, value: stamp },\n      ]);\n      next.stamp = stamp;\n      next.voices[index] = {\n        ...emptyVoice(),\n        active: true,\n        note: event.note,\n        gate: 1,\n        stamp,\n        owner,\n        channel,\n        startedAt: event.at,\n        velocity,\n        keyDown: 1,\n        envelopeStage: 'attack',\n      };\n    } else\n      for (const [index, voice] of next.voices.entries()) {\n        if (\n          voice.gate &&\n          voice.note === event.note &&\n          voice.owner === owner &&\n          voice.channel === channel\n        ) {\n          voice.keyDown = 0;\n          if (next.sustain?.[owner + ':' + channel]) continue;\n          releaseVoice(session, index);\n          voice.gate = 0;\n          voice.releasedAt = event.at;\n          voice.releaseLevel = voice.envelopeLevel;\n          voice.envelopeStage = 'release';\n        }\n      }\n    return next;\n  }\n\n  return { graph, view, paint, onControl, onEvent, eventState, eventStateSchema };\n}\n";
